#[test]
fn a_nul_glued_to_a_number_ends_the_number_7437() -> Result<()> {
    for (input, stdout, exit) in ROWS {
        let (out, _, code) = run_jq_full(&["-c", "."], Some(input))?;
        assert_eq!((out.as_str(), code), (*stdout, *exit), "{input:?}");
    }
    Ok(())
}

