#[test]
fn the_rows_jq_reads_read_the_same_on_every_route_7437() -> Result<()> {
    let text: String = ROWS
        .iter()
        .filter(|(_, _, exit)| *exit == 0)
        .map(|(input, _, _)| *input)
        .collect();
    for (args, stdout, exit) in STREAM_ROUTES {
        let (out, _, code, _) = run_jq_over_byte_files(args, &[text.as_bytes()])?;
        assert_eq!((out.as_str(), code), (*stdout, *exit), "file {args:?}");
        let (out, _, code) = run_jq_full(args, Some(&text))?;
        assert_eq!((out.as_str(), code), (*stdout, *exit), "stdin {args:?}");
    }
    Ok(())
}

