fn fromjson_ends_a_number_at_a_nul_7437() -> Result<()> {
    let input = serde_json::to_string(FROMJSON_TEXTS)?;
    let (out, _, code) = run_jq_full(
        &["-c", ".[] | try fromjson catch (\"E: \" + .)"],
        Some(&input),
    )?;
    assert_eq!((out.as_str(), code), (FROMJSON_OUT, 0));
    Ok(())
}

/// jq reads a line 4,095 bytes at a time, and a read with no newline only up to its first NUL
/// (#5654): `(BOM, spaces, then, jq -c . stdout, exit)`. The BOM is part of the first read. A NUL
/// in the first read of a longer line is not seen by jq 1.7.1, which stops at it and so reads the
/// token `1x` (jq 1.8.2 reads `[1,2]` there: #5654's section of the limitations page).
type ReadRow = (&'static [u8], usize, &'static [u8], &'static str, i32);

const READ_ROWS: &[ReadRow] = &[
    (b"\xef\xbb\xbf", 4091, b"1\0 \n", "1\n", 0),
    (b"", 5000, b"[1\0x,2]\n", "[1,2]\n", 0),
    (b"", 4093, b"[1\0x,2]\n", "[1,2]\n", 0),
    (b"", 4092, b"[1\0x,2]\n", "", 5),
];

#[test]
fn only_a_nul_in_a_read_that_holds_a_newline_is_read_past_7437() -> Result<()> {
    for (bom, spaces, then, stdout, exit) in READ_ROWS {
        let text = [*bom, &vec![b' '; *spaces], *then].concat();
        let (out, _, code, _) = run_jq_over_byte_files(&["-c", "."], &[&text])?;
        assert_eq!((out.as_str(), code), (*stdout, *exit), "{spaces} {then:?}");
    }
    Ok(())
}
